select

from approval_countersign
where 1 = 1

      and business_type = #{businessType}


      and business_id = #{businessId}


      and assignee_name like concat('%', #{assigneeName}, '%')


      and status = #{status}

order by created_at desc, id desc

select count(1)
from approval_countersign
where business_type = #{businessType}
  and business_id = #{businessId}
  and status = '待加签'
